            StateStore st=new StateStore(tmp.resolve("action-title-fallback-state"));Core c=new Core(st);Core.RepositoryConfig target=c.registerRepository("Fallback",r);c.chatBridgeService().replaceInventory(List.of(chatConversation("convE2345678","Duplicate",321),chatConversation("convF2345678","Duplicate",322)));
            String cs1=UUID.randomUUID().toString();PackageFixture p1=makePackage(repoId,cs1,"missing title",List.of(op("a.txt","replace","base","a1")));String a1="OBS-ACTION/1\naction: apply-package\nname: missing\narchive: "+p1.path.getFileName()+"\npackageId: "+p1.packageId+"\nchatTabTitle: Not Open";
