        test("Git-backed Commit failure leaves AppliedUncommitted and retries without reapplying files",()->{WorkspaceRepo w=workspaceRepo("workspace-commit-failure");String cs=UUID.randomUUID().toString();Core.ChangeSet created=w.core.startChangeSetWorkspace(w.target.id(),cs,"workspace commit failure","main").changeSet();Path wt=Path.of(created.worktree);PackageFixture p=makePackage(w.identity,cs,"workspace commit failure",List.of(op("seed.txt","replace","seed","next")));w.core.applyPackage(p.path,w.repo);g(wt,"config","user.name","");g(wt,"config","user.email","");expect(Core.COMMIT_FAILED,()->w.core.commitAppliedPackage(cs));eq(w.core.getChangeSet(cs).executionState,"AppliedUncommitted","failed Commit advanced execution state");eq(read(wt.resolve("seed.txt")),"next","failed Commit changed applied bytes");g(wt,"config","user.name","OBS Test");g(wt,"config","user.email","obs@example.invalid");Core.CommitResult retried=w.core.commitAppliedPackage(cs);eq(retried.changeSet().executionState,"CommittedUnpublished","Commit retry did not continue from AppliedUncommitted");eq(read(wt.resolve("seed.txt")),"next","Commit retry reapplied or changed package bytes");});
        test("Git-backed Commit and same-package Apply are idempotent after local commit",()->{WorkspaceRepo w=workspaceRepo("workspace-commit-repeat");String cs=UUID.randomUUID().toString();w.core.startChangeSetWorkspace(w.target.id(),cs,"workspace commit repeat","main");PackageFixture p=makePackage(w.identity,cs,"workspace commit repeat",List.of(op("seed.txt","replace","seed","next")));w.core.applyPackage(p.path,w.repo);Core.CommitResult first=w.core.commitAppliedPackage(cs),repeat=w.core.commitAppliedPackage(cs);ok(repeat.alreadySatisfied(),"repeat Commit did not report already satisfied");eq(repeat.commitSha(),first.commitSha(),"repeat Commit created another commit");Core.ApplyResult same=w.core.applyPackage(p.path,w.repo);eq(same.changeSet().executionState,"CommittedUnpublished","same-package Apply regressed committed state");ok(same.diagnostic().contains("CommittedUnpublished"),"same-package Apply did not report committed satisfaction");PackageFixture different=makePackage(w.identity,cs,"workspace commit repeat",List.of(op("seed.txt","replace","next","later")));expect(Core.STATE_DIVERGED,()->w.core.applyPackage(different.path,w.repo));eq(g(Path.of(first.changeSet().worktree),"rev-parse","HEAD").first(),first.commitSha(),"different package changed committed tip");});
        test("Git-backed Commit trailer proof ignores ChangeSet label lines that look like authority trailers",()->{WorkspaceRepo w=workspaceRepo("workspace-commit-label-trailer");String cs=UUID.randomUUID().toString(),label="Package-Id: unrelated label";w.core.startChangeSetWorkspace(w.target.id(),cs,label,"main");PackageFixture p=makePackage(w.identity,cs,label,List.of(op("seed.txt","replace","seed","next")));w.core.applyPackage(p.path,w.repo);Core.CommitResult first=w.core.commitAppliedPackage(cs);eq(first.changeSet().executionState,"CommittedUnpublished","label/trailer collision blocked Commit");String message=g(Path.of(first.changeSet().worktree),"show","-s","--format=%B",first.commitSha()).joined();ok(message.startsWith(label),"fixture did not preserve trailer-looking label in commit subject");Core.CommitResult repeat=w.core.commitAppliedPackage(cs);ok(repeat.alreadySatisfied(),"trailer-block proof did not verify committed state on repeat");eq(repeat.commitSha(),first.commitSha(),"trailer-looking label caused repeat Commit to create/change commit");});
        test("Git-backed Commit recovers exact package commit after crash before state persistence",()->{WorkspaceRepo w=workspaceRepo("workspace-commit-recover");String cs=UUID.randomUUID().toString(),base=g(w.repo,"rev-parse","HEAD").first();Core.ChangeSet created=w.core.startChangeSetWorkspace(w.target.id(),cs,"workspace commit recovery","main").changeSet();Path wt=Path.of(created.worktree);PackageFixture p=makePackage(w.identity,cs,"workspace commit recovery",List.of(op("seed.txt","replace","seed","next")));w.core.applyPackage(p.path,w.repo);g(wt,"add","-A","--","seed.txt");g(wt,"-c","commit.gpgsign=false","commit","--no-verify","--allow-empty","-m","workspace commit recovery","-m","Package-Id: "+p.packageId+"\nChangeSet-Id: "+cs);String committedHead=g(wt,"rev-parse","HEAD").first();eq(g(wt,"rev-parse",committedHead+"^").first(),base,"crash fixture parent mismatch");eq(w.core.getChangeSet(cs).executionState,"AppliedUncommitted","crash fixture unexpectedly persisted commit state");Core.CommitResult recovered=w.core.commitAppliedPackage(cs);ok(recovered.alreadySatisfied(),"commit crash recovery did not report established side effect");eq(recovered.commitSha(),committedHead,"commit crash recovery changed exact commit");eq(recovered.changeSet().executionState,"CommittedUnpublished","commit crash recovery did not persist state");});
