        test("Git-backed Apply retry preserves unknown crash bytes then restores prior and reapplies",()->{WorkspaceRepo w=workspaceRepo("workspace-apply-recover-partial-write");String cs=UUID.randomUUID().toString();Core.ChangeSet created=w.core.startChangeSetWorkspace(w.target.id(),cs,"workspace partial write recovery","main").changeSet();Path wt=Path.of(created.worktree);PackageFixture p=makePackage(w.identity,cs,"workspace partial write recovery",List.of(op("seed.txt","replace","seed","replacement-value")));w.core.applyPackage(p.path,w.repo);Core.ChangeSet simulatedCrash=w.core.getChangeSet(cs);simulatedCrash.executionState="Ready";simulatedCrash.lastPackageId=null;w.state.saveChangeSet(simulatedCrash);write(wt.resolve("seed.txt"),"repl");Core.ApplyResult recovered=w.core.applyPackage(p.path,w.repo);eq(recovered.changeSet().executionState,"AppliedUncommitted","partial-write recovery did not return to AppliedUncommitted");eq(read(wt.resolve("seed.txt")),"replacement-value","partial-write recovery result wrong");Path recovery=w.state.applyRecoveryDir(cs);ok(Files.isDirectory(recovery),"unknown partial bytes were not preserved before recovery");try(var ds=Files.newDirectoryStream(recovery,"unexpected-*.json")){Iterator<Path> it=ds.iterator();ok(it.hasNext(),"unknown partial recovery evidence missing");Map<String,Object> evidence=w.state.readObject(it.next());@SuppressWarnings("unchecked") List<Object> entries=(List<Object>)evidence.get("entries");@SuppressWarnings("unchecked") Map<String,Object> first=(Map<String,Object>)entries.get(0);eq(new String(Base64.getDecoder().decode(String.valueOf(first.get("bytesBase64"))),StandardCharsets.UTF_8),"repl","unknown partial bytes were not preserved exactly");}});
